import numpy as np
from PIL import Image
z=np.load('/app/output/debug_strokes.npz')
T=np.asarray(Image.open('/app/target.png').convert('RGB')).mean(2)<132
m=[]
for i in range(7):
 r,c=map(int,z[f'bbox_{i}']); a=z[f'mask_{i}']>=128
 f=np.zeros((1024,1024),bool);f[r:r+a.shape[0],c:c+a.shape[1]]=a;m.append(f)
def shift(a,dr,dc):return np.roll(np.roll(a,dr,0),dc,1)
offs=[(0,0)]*7

def quality(offs):
 P=np.zeros_like(T)
 for a,(dr,dc) in zip(m,offs):P|=shift(a,dr,dc)
 I=(P&T).sum();U=(P|T).sum()
 return I/U,I/P.sum(),I/T.sum(),P.sum()
print('initial',quality(offs), 'target',T.sum())
# coarse coordinate descent, each pixel in range ±24
for sweep,rad,step in [(0,24,3),(1,5,1),(2,2,1)]:
 print('SWEEP',sweep)
 for k in range(7):
  best=-1; bi=offs[k]
  other=np.zeros_like(T)
  for j,a in enumerate(m):
   if j!=k:other|=shift(a,*offs[j])
  for dr in range(offs[k][0]-rad,offs[k][0]+rad+1,step):
   for dc in range(offs[k][1]-rad,offs[k][1]+rad+1,step):
    P=other|shift(m[k],dr,dc)
    inter=(P&T).sum(); union=P.sum()+T.sum()-inter
    score=inter/union
    if score>best:best=score;bi=(dr,dc)
  offs[k]=bi
  print(k,bi,round(best,5),quality(offs))
 print('offs',offs)
np.save('/tmp/offsets.npy',np.array(offs))
